const res = $input.first().json;
const code = Number(res.statusCode ?? 0);

if (code >= 400) {
  throw new Error(
    `Login a n8n falló (HTTP ${code}). Revisá N8N_URL / N8N_EMAIL / N8N_PASSWORD en el nodo Config. ` +
    `Respuesta: ${JSON.stringify(res.body ?? {}).slice(0, 300)}`
  );
}

const raw = res.headers?.['set-cookie'] ?? [];
const lista = Array.isArray(raw) ? raw : [raw];
const auth = lista.map(String).find((c) => c.startsWith('n8n-auth='));

if (!auth) {
  throw new Error(
    'El login respondió OK pero no mandó la cookie n8n-auth. ' +
    'Si ese usuario tiene 2FA o SSO, este método no sirve — ver la nota amarilla.'
  );
}

return [{ json: { cookie: auth.split(';')[0] } }];

const cfg = $('Config').first().json;
const dias = Number(cfg.DIAS_ATRAS) || 3;
const maxAnalizar = Number(cfg.MAX_ANALIZAR) || 40;
const desde = Date.now() - dias * 86400000;

const todas = $input.all().map((i) => i.json);

const candidatas = todas.filter((e) => {
  if (e.status !== 'error') return false;
  if (e.finished === true) return false;        // terminó bien, no se puede reintentar
  if (e.retrySuccessId) return false;           // ya la reintentaron y salió OK
  return new Date(e.startedAt).getTime() >= desde;
});

// más recientes primero para el recorte, después cronológico para ejecutar
candidatas.sort((a, b) => new Date(b.startedAt) - new Date(a.startedAt));
const analizar = candidatas.slice(0, maxAnalizar);
const sinAnalizar = candidatas.length - analizar.length;
analizar.sort((a, b) => new Date(a.startedAt) - new Date(b.startedAt));

console.log(
  `[preseleccion] la API devolvió ${todas.length} | con error en los últimos ${dias} días: ${candidatas.length} | ` +
  `se analizan ${analizar.length}` +
  (sinAnalizar > 0 ? ` | QUEDAN ${sinAnalizar} SIN ANALIZAR (subí MAX_ANALIZAR o volvé a correr)` : '')
);

if (!analizar.length) {
  console.log('[preseleccion] no hay nada para reintentar en la ventana pedida.');
}

return analizar.map((e) => ({ json: { id: String(e.id), startedAt: e.startedAt, mode: e.mode } }));

const cfg = $('Config').first().json;
const nodosObjetivo = String(cfg.NODOS_OBJETIVO || '')
  .split(',')
  .map((s) => s.trim())
  .filter(Boolean);
const firma = String(cfg.FIRMA_ERROR || '').trim();

const ex = $input.first().json;
const rd = ex?.data?.resultData ?? {};
const err = rd.error ?? {};
const stack = ex?.data?.executionData?.nodeExecutionStack ?? [];

// datos del lead: el nodo All_Data del flujo de HPF los deja todos juntos
const lead = rd.runData?.All_Data?.[0]?.data?.main?.[0]?.[0]?.json ?? {};

const textoError = [err.message, err.description]
  .concat(Array.isArray(err.messages) ? err.messages : [])
  .filter(Boolean)
  .join(' | ');

const nodoQueFallo = rd.lastNodeExecuted ?? null;
const nodoDeReanudacion = stack[0]?.node?.name ?? null;

let motivo = null;
if (!stack.length) {
  motivo = 'sin nodeExecutionStack — n8n no puede reanudarla';
} else if (nodosObjetivo.length && !nodosObjetivo.includes(nodoQueFallo)) {
  motivo = `falló en "${nodoQueFallo}", fuera de NODOS_OBJETIVO`;
} else if (firma && !textoError.includes(firma)) {
  motivo = `el error no contiene "${firma}"`;
}

return [{
  json: {
    accion: motivo ? 'skip' : 'retry',
    motivo,
    id: String(ex.id),
    startedAt: ex.startedAt,
    nodoQueFallo,
    nodoDeReanudacion,
    lead: lead.entity_id ?? null,
    contacto: lead.contact_id ?? null,
    telefono: lead.numero_telefono ?? null,
    mensaje: String(lead.text ?? '').slice(0, 120),
    error: textoError.slice(0, 250),
  },
}];

const sd = $getWorkflowStaticData('global');
sd.fallosSeguidos = 0;
sd.ok = 0;
sd.fail = 0;

const cfg = $('Config').first().json;
const todas = $input.all().map((i) => i.json);

let retry = todas.filter((i) => i.accion === 'retry');
const skip = todas.filter((i) => i.accion !== 'retry');

retry.sort((a, b) => new Date(a.startedAt) - new Date(b.startedAt));

// dedupe: si un lead tiene varios fallos, dejamos solo el más reciente
let dedupe = [];
if (cfg.SOLO_ULTIMA_POR_LEAD === true) {
  const ultimaPorLead = new Map();
  for (const e of retry) ultimaPorLead.set(String(e.lead ?? e.contacto ?? e.id), e.id);
  const conservar = new Set(ultimaPorLead.values());
  dedupe = retry.filter((e) => !conservar.has(e.id));
  retry = retry.filter((e) => conservar.has(e.id));
}

const tope = Number(cfg.MAX_POR_CORRIDA) || retry.length;
const recortadas = retry.slice(tope);
retry = retry.slice(0, tope);

console.log(
  `[clasificar] analizadas=${todas.length} | a_reintentar=${retry.length} | ` +
  `descartadas=${skip.length} | omitidas_por_dedupe=${dedupe.length} | recortadas_por_tope=${recortadas.length}`
);

return [
  ...retry.map((json) => ({ json })),
  ...skip.map((json) => ({ json })),
  ...dedupe.map((json) => ({
    json: { ...json, accion: 'skip', motivo: 'dedupe: ese lead tiene un fallo más reciente' },
  })),
  ...recortadas.map((json) => ({
    json: { ...json, accion: 'skip', motivo: `recortada por MAX_POR_CORRIDA=${tope}` },
  })),
];

const sd = $getWorkflowStaticData('global');
const meta = $('Loop retry').first().json;
const res = $input.first().json;

const code = Number(res.statusCode ?? 0);
const body = res.body ?? {};

let estado;
let detalle;

if (code >= 200 && code < 300) {
  if (body?.data === true) {
    estado = 'OK';
    detalle = 'la ejecución reanudada terminó bien';
  } else {
    estado = 'REANUDADA_PERO_FALLO';
    detalle = 'n8n la reanudó pero volvió a fallar — mirá la ejecución nueva en la UI';
  }
} else if (code === 502 || code === 503 || code === 504) {
  estado = 'TIMEOUT_PROXY';
  detalle = `HTTP ${code}: es muy probable que haya corrido igual. Verificá en la UI ANTES de re-disparar.`;
} else if (code === 401 || code === 403) {
  estado = 'SIN_SESION';
  detalle = `HTTP ${code}: la cookie no sirve o expiró`;
} else {
  estado = 'ERROR';
  detalle = `HTTP ${code}: ${JSON.stringify(body).slice(0, 200)}`;
}

if (estado === 'OK') {
  sd.ok = (sd.ok || 0) + 1;
  sd.fallosSeguidos = 0;
} else if (estado !== 'TIMEOUT_PROXY') {
  sd.fail = (sd.fail || 0) + 1;
  sd.fallosSeguidos = (sd.fallosSeguidos || 0) + 1;
}

console.log(`[retry] exec=${meta.id} lead=${meta.lead} tel=${meta.telefono} → ${estado}`);

// circuit breaker: si 3 seguidos fallan, no tiene sentido seguir quemando ejecuciones
if ((sd.fallosSeguidos || 0) >= 3) {
  throw new Error(
    `Corté la corrida: 3 reintentos seguidos fallaron. Último: ${estado} — ${detalle}. ` +
    `Si es la cuota de Airtable, revisá el uso antes de volver a correr.`
  );
}

return [{ json: { ...meta, estado, detalle, httpCode: code } }];

const cfg = $('Config').first().json;
const simulacro = cfg.DRY_RUN === true;

const todas = $('Clasificar').all().map((i) => i.json);
const entrada = $input.all().map((i) => i.json);

const aReintentar = todas.filter((i) => i.accion === 'retry');
const descartadas = todas.filter((i) => i.accion !== 'retry');

const porMotivo = descartadas.reduce((acc, d) => {
  const k = d.motivo || 'sin motivo';
  acc[k] = (acc[k] || 0) + 1;
  return acc;
}, {});

const porEstado = {};
if (!simulacro) {
  for (const r of entrada) porEstado[r.estado] = (porEstado[r.estado] || 0) + 1;
}

const l = [];
l.push(simulacro ? '=== SIMULACRO (DRY_RUN = true) — no se reintentó nada ===' : '=== CORRIDA REAL ===');
l.push(`Ejecuciones analizadas : ${todas.length}`);
l.push(`A reintentar           : ${aReintentar.length}`);
l.push(`Descartadas            : ${descartadas.length}`);
for (const [motivo, n] of Object.entries(porMotivo)) l.push(`   · ${motivo}: ${n}`);

if (!simulacro) {
  l.push('Resultado de los reintentos:');
  for (const [k, v] of Object.entries(porEstado)) l.push(`   · ${k}: ${v}`);
} else {
  l.push('');
  l.push('Se reintentarían (id | nodo donde reanuda | lead | mensaje):');
  for (const c of aReintentar) {
    l.push(`   · ${c.id} | ${c.nodoDeReanudacion} | ${c.lead} | ${c.mensaje}`);
  }
}

console.log(l.join('\n'));

return [{
  json: {
    modo: simulacro ? 'simulacro' : 'real',
    analizadas: todas.length,
    a_reintentar: aReintentar.length,
    descartadas: descartadas.length,
    descartadas_por_motivo: porMotivo,
    resultados: porEstado,
    detalle: simulacro ? aReintentar : entrada,
  },
}];
